#!/bin/bash
# PreToolUse gate on ExitPlanMode. Blocks plan finalization until a
# writing-refinement pass has run in this session. Fails open: any missing
# input, unreadable transcript, or parse error allows the call through.
# Set WORKFLOW_HOOKS_WRITING_GATE=off to disable.

if [ "${WORKFLOW_HOOKS_WRITING_GATE:-}" = "off" ]; then
  exit 0
fi

python3 - <<'EOF'
import json, re, sys

try:
    payload = json.load(sys.stdin)
except Exception:
    sys.exit(0)  # fail open on unparseable payload

transcript = payload.get("transcript_path")
if not transcript:
    sys.exit(0)

# A refinement pass shows up as a sub-agent dispatch (Agent/Task) or a Skill
# call whose input mentions writing-refinement. Matching the serialized input
# catches every dispatch shape: subagent_type, prompt text, or skill name.
PATTERN = re.compile(r"writing[-_ ]?refinement", re.I)
TOOL_NAMES = {"Agent", "Task", "Skill"}

found = False
try:
    with open(transcript) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                continue
            message = obj.get("message")
            content = message.get("content") if isinstance(message, dict) else None
            if not isinstance(content, list):
                continue
            for block in content:
                if not isinstance(block, dict) or block.get("type") != "tool_use":
                    continue
                if block.get("name") not in TOOL_NAMES:
                    continue
                if PATTERN.search(json.dumps(block.get("input", {}))):
                    found = True
                    break
            if found:
                break
except Exception:
    sys.exit(0)  # fail open if the transcript can't be read

if found:
    sys.exit(0)

reason = (
    "Writing-review gate: finalize a plan only after a writing-refinement pass. "
    "This session records no writing-refinement run. Launch the writing-refinement skill "
    "as a sub-agent over the plan (dispatch an Agent whose prompt invokes /writing-refinement, "
    "or call the writing-refinement Skill), apply its findings to the plan file, then call "
    "ExitPlanMode again. To bypass — for example when using an alternative refiner — set "
    "WORKFLOW_HOOKS_WRITING_GATE=off."
)
print(json.dumps({
    "hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny",
        "permissionDecisionReason": reason,
    }
}))
EOF

